class Column;
class ProvenanceColumn;
class Rows;
class RowsSome;
class Role;
class Event;
class Member;
class HeaderColumns;
class ProvenanceColumns;

namespace detail {
struct TelemetryAccess;
}  // namespace detail

/// One column of an event table, in wire order.
class Column {
public:
    /// The SQL column name, also the struct field name.
    const std::string& GetName() const { return name_; }
    /// The lake type; its byte width is the wire width.
    SqlType GetSql() const { return sql_; }
    /// How the column is streamed.
    FieldKind GetKind() const { return kind_; }
    /// The telemetry enum an `enum8` column holds.
    std::optional<Vocabulary> GetValues() const { return values_; }
    /// The version that added the column; none: present from the table's first known version.
    std::optional<int64_t> GetSince() const { return since_; }
    /// The version that retired it. A retired column stays in the DDL (after the live ones),
    /// is appended as NULL, and leaves the wire.
    std::optional<int64_t> GetRetiredIn() const { return retiredIn_; }

private:
    friend struct detail::TelemetryAccess;

    std::string name_;
    SqlType sql_{};
    FieldKind kind_{};
    std::optional<Vocabulary> values_;
    std::optional<int64_t> since_;
    std::optional<int64_t> retiredIn_;
};

/// A provenance column the ingester prepends to every table: who sent the row, in which
/// batch, at which version. Never on the wire as a field.
class ProvenanceColumn {
public:
    /// Its SQL name.
    const std::string& GetName() const { return name_; }
    /// Its SQL type, never NULL.
    SqlType GetSql() const { return sql_; }

private:
    friend struct detail::TelemetryAccess;

    std::string name_;
    SqlType sql_{};
};

/// A member of vocabulary `v`: what a ledger role splitting on a `v` column names.
class Member {
public:
    MemberBranch GetBranch() const { return static_cast<MemberBranch>(value_.index()); }
    std::optional<FarmEventKind> AsFarmEventKind() const { const auto* p = std::get_if<0>(&value_); return p ? std::optional<FarmEventKind>(*p) : std::nullopt; }
    std::optional<SovereignEventKind> AsSovereignEventKind() const { const auto* p = std::get_if<1>(&value_); return p ? std::optional<SovereignEventKind>(*p) : std::nullopt; }
    std::optional<SovereignRole> AsSovereignRole() const { const auto* p = std::get_if<2>(&value_); return p ? std::optional<SovereignRole>(*p) : std::nullopt; }
    std::optional<SovereignDoctrine> AsSovereignDoctrine() const { const auto* p = std::get_if<3>(&value_); return p ? std::optional<SovereignDoctrine>(*p) : std::nullopt; }
    std::optional<SovereignPower> AsSovereignPower() const { const auto* p = std::get_if<4>(&value_); return p ? std::optional<SovereignPower>(*p) : std::nullopt; }
    std::optional<LifecycleKind> AsLifecycleKind() const { const auto* p = std::get_if<5>(&value_); return p ? std::optional<LifecycleKind>(*p) : std::nullopt; }
    std::optional<GrantKind> AsGrantKind() const { const auto* p = std::get_if<6>(&value_); return p ? std::optional<GrantKind>(*p) : std::nullopt; }

private:
    friend struct detail::TelemetryAccess;

    std::variant<FarmEventKind, SovereignEventKind, SovereignRole, SovereignDoctrine, SovereignPower, LifecycleKind, GrantKind> value_;
};

/// The rows whose `column` holds one of `kinds`, members of the column's vocabulary.
class RowsSome {
public:
    /// The enum8 column that splits the rows.
    const std::string& GetColumnKey() const { return column_; }
    /// Its vocabulary, so the kinds are typed.
    Vocabulary GetOf() const { return of_; }
    /// The members covered.
    const std::vector<Member>& GetKinds() const { return kinds_; }

private:
    friend struct detail::TelemetryAccess;

    std::string column_;
    Vocabulary of_{};
    std::vector<Member> kinds_;
};

/// The rows of a table one ledger role covers.
class Rows {
public:
    RowsKind GetKind() const { return static_cast<RowsKind>(value_.index()); }
    const RowsSome* AsSome() const { return std::get_if<1>(&value_); }

private:
    friend struct detail::TelemetryAccess;

    std::variant<std::monostate, RowsSome> value_;
};

/// One ledger leg a table's rows contribute, or the statement that they move nothing.
class Role {
public:
    /// The rows it covers.
    const Rows& GetRows() const { return rows_; }
    /// What moves.
    Currency GetCurrency() const { return currency_; }
    /// Mint, sink or transfer.
    Bucket GetBucket() const { return bucket_; }
    /// +1 credit, -1 debit, 0: the amount is already signed (or there is none).
    int64_t GetSign() const { return sign_; }
    /// The stable vocabulary the economy panel groups on.
    const std::string& GetToken() const { return token_; }
    /// The side a single-row transfer reads; none for a table with one row per side.
    std::optional<Leg> GetLeg() const { return leg_; }
    /// An extra predicate on the table's own columns (DuckDB SQL).
    const std::string* GetFilter() const { return filter_ ? &*filter_ : nullptr; }
    /// The magnitude; none for a row that documents a path with no amount.
    const std::string* GetAmountKey() const { return amount_ ? &*amount_ : nullptr; }
    /// For item legs: the column naming the item.
    const std::string* GetItemKey() const { return item_ ? &*item_ : nullptr; }
    /// Whose ledger the leg lands on; none: the header's player_id.
    const std::string* GetPlayerKey() const { return player_ ? &*player_ : nullptr; }
    /// The other side, if any.
    const std::string* GetCounterpartyKey() const { return counterparty_ ? &*counterparty_ : nullptr; }
    /// Summed into the reconciliation (true), or real telemetry that must not be summed.
    bool GetCounted() const { return counted_; }
    /// The token this row would double-count with.
    const std::string* GetDedupOf() const { return dedupOf_ ? &*dedupOf_ : nullptr; }
    /// The last version whose rows this role reads; none: every version.
    std::optional<int64_t> GetUntilVersion() const { return untilVersion_; }
    /// Why, citing a function, never a line number.
    const std::string& GetNote() const { return note_; }

private:
    friend struct detail::TelemetryAccess;

    Rows rows_;
    Currency currency_{};
    Bucket bucket_{};
    int64_t sign_ = 0;
    std::string token_;
    std::optional<Leg> leg_;
    std::optional<std::string> filter_;
    std::optional<std::string> amount_;
    std::optional<std::string> item_;
    std::optional<std::string> player_;
    std::optional<std::string> counterparty_;
    bool counted_ = false;
    std::optional<std::string> dedupOf_;
    std::optional<int64_t> untilVersion_;
    std::string note_;
};

/// One telemetry table: the rows of one event type.
class Event {
public:
    /// What one row records.
    const std::string& GetDescription() const { return description_; }
    /// The current layout version: the wire version byte and the lake's event_version.
    uint8_t GetVersion() const { return version_; }
    /// The first version whose layout this catalogue knows. Tables older than the schema lock
    /// start at 2, its floor; their earlier history is lost.
    int64_t GetSince() const { return since_; }
    /// Ring policy.
    Tier GetTier() const { return tier_; }
    /// The processes that own a ring for it (none: read-only history).
    const std::vector<Producer>& GetProducers() const { return producers_; }
    /// How the client enqueues it.
    Enqueue GetEnqueue() const { return enqueue_; }
    /// The body columns after the header, in wire order, retired ones where they stood.
    const canon::KeyedList<std::string, Column>& GetColumns() const { return columns_; }
    /// What its rows mean to the ledgers; empty: no ledger at all.
    const std::vector<Role>& GetLedger() const { return ledger_; }
    /// The enum8 column the ledger is typed by. When set, every live member of its vocabulary
    /// is covered by some role (L-0111), so a new kind cannot ship without a ledger decision.
    const std::string* GetLedgerKindsKey() const { return ledgerKinds_ ? &*ledgerKinds_ : nullptr; }

private:
    friend struct detail::TelemetryAccess;

    std::string description_;
    uint8_t version_ = 0;
    int64_t since_ = 0;
    Tier tier_{};
    std::vector<Producer> producers_;
    Enqueue enqueue_{};
    canon::KeyedList<std::string, Column> columns_;
    std::vector<Role> ledger_;
    std::optional<std::string> ledgerKinds_;
};

/// The two header columns every table starts with; `since` is the table's first version.
class HeaderColumns {
public:
    HeaderColumns() = default;
    HeaderColumns(const HeaderColumns&) = delete;
    HeaderColumns& operator=(const HeaderColumns&) = delete;
    HeaderColumns(HeaderColumns&&) = default;
    HeaderColumns& operator=(HeaderColumns&&) = default;

    size_t Len() const { return rows_.All().size(); }
    const Column& At(size_t i) const { return rows_.At(i); }
    const std::vector<Column>& All() const { return rows_.All(); }
    /// Binary search by name. Never allocates; nullptr when absent.
    const Column* Find(std::string_view name) const { return rows_.Find(name); }

private:
    friend struct detail::TelemetryAccess;

    canon::KeyedList<std::string, Column> rows_;
};

/// The provenance prefix of every CREATE TABLE, in order.
class ProvenanceColumns {
public:
    ProvenanceColumns() = default;
    ProvenanceColumns(const ProvenanceColumns&) = delete;
    ProvenanceColumns& operator=(const ProvenanceColumns&) = delete;
    ProvenanceColumns(ProvenanceColumns&&) = default;
    ProvenanceColumns& operator=(ProvenanceColumns&&) = default;

    size_t Len() const { return rows_.All().size(); }
    const ProvenanceColumn& At(size_t i) const { return rows_.At(i); }
    const std::vector<ProvenanceColumn>& All() const { return rows_.All(); }
    /// Binary search by name. Never allocates; nullptr when absent.
    const ProvenanceColumn* Find(std::string_view name) const { return rows_.Find(name); }

private:
    friend struct detail::TelemetryAccess;

    canon::KeyedList<std::string, ProvenanceColumn> rows_;
};

